from .money import _MAX_CENTS, _cents_to_decimal, _to_cents, format_amount, parse_amount


def make_invoice(amounts):
    if not isinstance(amounts, list):
        raise ValueError("amounts must be a list")
    items = list(amounts)
    total = 0
    for item in items:
        total += _to_cents(item)
        if total > _MAX_CENTS:
            raise ValueError("invoice total exceeds 1000000.00")
    return {"total": format_amount(_cents_to_decimal(total)), "count": len(items)}

