import re
from decimal import Decimal

_AMOUNT_RE = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?", re.ASCII)
_MAX_CENTS = 100_000_000  # 1000000.00


def _to_cents(value):
    """Validate an amount and return it as an exact integer number of cents.

    Uses only integer arithmetic and exact Decimal construction, so the
    result never depends on the active decimal context.
    """
    if isinstance(value, bool):
        raise ValueError("bool is not a valid amount")
    if isinstance(value, int):
        cents = int(value) * 100
    elif isinstance(value, str):
        if _AMOUNT_RE.fullmatch(value) is None:
            raise ValueError(f"invalid amount string: {value!r}")
        # Decimal string construction is exact and independent of precision.
        cents = _decimal_to_cents(Decimal(value))
    elif isinstance(value, Decimal):
        cents = _decimal_to_cents(value)
    else:
        raise ValueError(f"unsupported amount type: {type(value).__name__}")
    if cents <= 0:
        raise ValueError("amount must be positive")
    if cents > _MAX_CENTS:
        raise ValueError("amount exceeds 1000000.00")
    return cents


def _decimal_to_cents(value):
    if not value.is_finite():
        raise ValueError("amount must be finite")
    sign, digits, exponent = value.as_tuple()
    # Drop trailing zeros so huge exponents never cause huge integer work.
    digits = list(digits)
    while len(digits) > 1 and digits[-1] == 0:
        digits.pop()
        exponent += 1
    if all(d == 0 for d in digits):
        raise ValueError("amount must be positive")
    if sign:
        raise ValueError("amount must be positive")
    if exponent < -2:
        raise ValueError("amount is not representable in whole cents")
    if len(digits) + exponent > 7:  # >= 10**7, certainly over the limit
        raise ValueError("amount exceeds 1000000.00")
    coefficient = int("".join(map(str, digits)))
    return coefficient * 10 ** (exponent + 2)


def _cents_to_decimal(cents):
    sign = "-" if cents < 0 else ""
    whole, frac = divmod(abs(cents), 100)
    return Decimal(f"{sign}{whole}.{frac:02d}")


def parse_amount(value):
    return _cents_to_decimal(_to_cents(value))


def format_amount(value):
    return format(value, ".2f")
